import {budgetForecast} from './economy.js?v=power-overload-grace-1';
import {loanRepaymentSchedule} from './loan-schedule.js?v=power-overload-grace-1';
const money=n=>'§'+Math.round(n).toLocaleString('en-US');
export function treasuryOutlook(city,months=12){
 if(!Number.isInteger(months)||months<1||months>120)throw Error('Choose a projection from 1 to 120 months.');
 const budget=budgetForecast(city),payments=new Map(loanRepaymentSchedule(city).map(row=>[row.month,row.total])),rows=[];let funds=city.funds,lowest={month:city.month,funds},firstShortfall=funds<0?{month:city.month,funds}:null;
 for(let offset=1;offset<=months;offset++){const month=city.month+offset,opening=funds,loanPayment=payments.get(month)||0;funds+=budget.balance-loanPayment;const row={month,opening,operating:budget.balance,loanPayment,funds};rows.push(row);if(funds<lowest.funds)lowest={month,funds};if(!firstShortfall&&funds<0)firstShortfall={month,funds};}
 const debtDue=rows.reduce((sum,row)=>sum+row.loanPayment,0),nextPayment=loanRepaymentSchedule(city).find(row=>row.month>city.month)||null;
 return{months,budget,rows,lowest,firstShortfall,nextPayment,debtDue,ending:funds};
}
export function financialAdvice(city,outlook=treasuryOutlook(city)){const issues=[];
 if(city.funds<0)issues.push({title:'The treasury is already negative',text:'Monthly commitments continue even when cash runs out. Review recurring spending and revenue before planning construction.',action:'budget'});
 else if(outlook.firstShortfall)issues.push({title:'A cash shortage is projected',text:`At unchanged operating conditions, the treasury becomes negative in ${outlook.firstShortfall.month-city.month} months. Check the dated projection and loan payments before committing more cash.`,action:'budget'});
 if(outlook.budget.balance<0)issues.push({title:'Recurring expenses exceed income',text:`Current operations use ${money(-outlook.budget.balance)} more than they bring in each month. A loan adds cash and repayment obligations; it does not fix this recurring deficit.`,action:'budget'});
 if(outlook.nextPayment)issues.push({title:'Reserve cash for loan payments',text:`The next combined payment is ${money(outlook.nextPayment.total)} in ${outlook.nextPayment.month-city.month} months. Loan repayments come on top of operating expenses; the timeline below includes them.`,action:'budget'});
 if(outlook.budget.spending.ordinances>0)issues.push({title:'Review policy value',text:'Compare the benefits and recurring costs of active ordinances. Repealing a policy saves its charge but also removes its effect.',action:'ordinances'});
 if(!issues.length)issues.push({title:'Protect the treasury',text:'No cash shortage is projected over this horizon at current conditions. Keep a reserve for construction, growth and emergencies; this outlook cannot predict them.',action:'budget'});
 return issues;
}
export function showFinancialAdvisor(ui,back,months=12){const c=ui.city(),outlook=treasuryOutlook(c,months),issues=financialAdvice(c,outlook),date=month=>new Date(Date.UTC(c.startYear+Math.floor(month/12),month%12)).toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'});
 ui.dialog('Mortimer Green',`<div class="civic-advisor-header"><img src="assets/mortimer-advisor.png" width="192" height="192" alt=""><div><p class="eyebrow">Financial advisor</p><h3>Your treasury outlook</h3><p>Keep recurring income ahead of expenses, and reserve cash for dated commitments.</p></div></div><dl class="civic-advisor-facts"><div><dt>Treasury now</dt><dd>${money(c.funds)}</dd></div><div><dt>Operating balance / month</dt><dd>${money(outlook.budget.balance)}</dd></div><div><dt>Lowest projected treasury</dt><dd>${money(outlook.lowest.funds)}</dd></div></dl>${issues.map(issue=>`<article class="civic-advisor-issue"><h3>${issue.title}</h3><p>${issue.text}</p><button data-financial-action="${issue.action}">${issue.action==='ordinances'?'Review ordinances':'Review budget & loans'}</button></article>`).join('')}<h3>Month-by-month cash projection</h3><label>Projection horizon<select id="treasuryHorizon">${[12,24,60,120].map(value=>`<option value="${value}" ${months===value?'selected':''}>${value/12} ${value===12?'year':'years'}</option>`).join('')}</select></label><p>${outlook.firstShortfall?`First projected negative treasury: ${date(outlook.firstShortfall.month)} · ${money(outlook.firstShortfall.funds)}.`:'No negative treasury projected over this horizon.'} Lowest point: ${date(outlook.lowest.month)}. Scheduled repayments: ${money(outlook.debtDue)}. Ending treasury: ${money(outlook.ending)}.</p><details><summary>Inspect ${months} monthly balances</summary><div class="table-scroll"><table><thead><tr><th scope="col">Month</th><th scope="col">Opening cash</th><th scope="col">Operating balance</th><th scope="col">Loan payments</th><th scope="col">Closing cash</th></tr></thead><tbody>${outlook.rows.map(row=>`<tr><th scope="row">${date(row.month)}</th><td>${money(row.opening)}</td><td>${money(row.operating)}</td><td>${money(row.loanPayment)}</td><td>${money(row.funds)}${row.funds<0?' · shortage':''}</td></tr>`).join('')}</tbody></table></div></details><p class="fine">Projection holds current income, expenses, population, land values and deal income constant, then subtracts scheduled loan repayments. Construction, future policy changes, contract expiry or penalties, growth, disasters and relief grants are excluded. Month-end balances do not predict every transaction within a month. No simulation time advances.</p><button id="backFinancialAdvisor">Back to budget</button>`);
 document.querySelector('#treasuryHorizon').onchange=event=>showFinancialAdvisor(ui,back,Number(event.target.value));document.querySelector('#backFinancialAdvisor').onclick=back;document.querySelectorAll('[data-financial-action]').forEach(button=>button.onclick=()=>button.dataset.financialAction==='ordinances'?ui.ordinances():back());
}
